using System;
using System.Collections.Generic;
using System.Linq;
using System.Runtime.InteropServices;
using System.Windows;
using System.Windows.Controls;
using Swivel.Core;
using Swivel.Windows;

internal static class AssistantNativeChecks
{
    private static IEnumerable<T> Find<T>(DependencyObject root)where T:DependencyObject
    {if(root is T v)yield return v;foreach(var child in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>())foreach(var found in Find<T>(child))yield return found;}
    internal static void Run(Action<bool,string> check,Action<Action,string> reject)
    {
        check(IntPtr.Size==8&&Marshal.SizeOf<AssistantCredentials.Credential>()==80,"Credential ABI x64/ARM64 size80");
        foreach(var p in new[]{("BlobSize",32),("Blob",40),("Persist",48),("AttributeCount",52),("Attributes",56),("TargetAlias",64),("UserName",72)})check(Marshal.OffsetOf<AssistantCredentials.Credential>(p.Item1).ToInt32()==p.Item2,"Credential ABI "+p.Item1);
        var app=Application.Current as App??throw new InvalidOperationException("Validation host required.");if(!app.IsValidationHost)throw new InvalidOperationException("No product credential tests.");
        var settings=new AssistantSettings(AssistantProvider.ChatCompletions,"http://127.0.0.1:11434/v1/chat/completions","fixture-model");
        var dialog=new AssistantDialog(app,settings,new[]{new AssistantChoice("file.paths","Copy Path")},Array.Empty<string>(),"Please suggest a copy action",default);
        var buttons=Find<Button>(dialog).ToArray();var send=buttons.Single(x=>Equals(x.Content,app.L("Send Reviewed Request")));var select=buttons.Single(x=>Equals(x.Content,app.L("Select Suggested Action")));
        check(!send.IsEnabled&&!select.IsEnabled&&dialog.SelectedId is null,"Assistant native no implicit request/action");
        buttons.Single(x=>Equals(x.Content,app.L("Prepare Request Preview"))).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
        var preview=Find<TextBox>(dialog).Single(x=>x.IsReadOnly&&x.Height==260);check(preview.Text==AssistantPlan.Create(settings,"Please suggest a copy action",new[]{new AssistantChoice("file.paths","Copy Path")},Array.Empty<string>()).Json,"Assistant native complete exact JSON preview");
        var review=Find<CheckBox>(dialog).Single(x=>Equals(x.Content,app.L("I reviewed the full JSON request and destination.")));check(!send.IsEnabled,"Assistant native requires explicit full-preview review");review.IsChecked=true;check(send.IsEnabled,"Assistant native review enables explicit send");
        Find<TextBox>(dialog).Single(x=>!x.IsReadOnly).Text="Different request";check(!send.IsEnabled&&!select.IsEnabled&&preview.Text.Length==0&&review.IsChecked==false,"Assistant native changing request invalidates preview and stale suggestion");
        var root=(DockPanel)dialog.Content;check(root.Children.OfType<ScrollViewer>().Any()&&root.Children.OfType<StackPanel>().Any(x=>DockPanel.GetDock(x)==Dock.Bottom),"Assistant native footer/scroll");dialog.Close();dialog.FinishAsync().GetAwaiter().GetResult();
        var config=new AssistantSettingsDialog(app);check(Find<PasswordBox>(config).Single().MaxLength==0,"Assistant native preserves over-limit key paste for explicit refusal");config.Close();check(app.Home is null&&app.Awake is null,"Assistant native fixture does not start settings/tray/services");
        var custom=new AssistantDialog(app,settings,new[]{new AssistantChoice("file.paths","Copy Path")},Array.Empty<string>(),"Choose an action",default,new[]{new AssistantChoice("preset.fixture","PRIVATE-LABEL")});
        var cb=Find<CheckBox>(custom).Single(x=>Equals(x.Content,app.L("Include custom app and preset labels in this request (may contain private information)")));var prep=Find<Button>(custom).Single(x=>Equals(x.Content,app.L("Prepare Request Preview")));prep.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var cp=Find<TextBox>(custom).Single(x=>x.Height==260);check(cb.IsChecked==false&&!cp.Text.Contains("PRIVATE-LABEL"),"Custom assistant labels default absent");cb.IsChecked=true;check(cp.Text.Length==0,"Custom consent invalidates existing request");prep.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(cp.Text.Contains("PRIVATE-LABEL"),"Explicit custom consent appears in full preview");custom.Close();custom.FinishAsync().GetAwaiter().GetResult();
        var facts=new[]{new DoctorFact("Uptime","{0} hours since the last system start",new object[]{5d})};var doctor=new AssistantDialog(app,settings,Array.Empty<AssistantChoice>(),Array.Empty<string>(),"Explain this snapshot",default,doctorFacts:facts);
        check(Find<TextBox>(doctor).Single(x=>x.Height==180).Text==DoctorAssistantReport.Create(facts),"Doctor separately shows exact redacted snapshot");check(Find<Button>(doctor).Single(x=>Equals(x.Content,app.L("Select Suggested Action"))).Visibility==Visibility.Collapsed&&!Find<Button>(doctor).Single(x=>Equals(x.Content,app.L("Copy Explanation"))).IsEnabled,"Doctor has no action selector or implicit clipboard delivery");doctor.Close();doctor.FinishAsync().GetAwaiter().GetResult();
        var folder=new FolderScanResult(new FolderSizeNode("PRIVATE-ROOT",true),0,false,false);var aggregate=DoctorAssistantSummary.Folder(folder);var aggregateDialog=new AssistantDialog(app,settings,Array.Empty<AssistantChoice>(),Array.Empty<string>(),"Explain this snapshot",default,doctorSnapshot:aggregate);
        check(Find<TextBox>(aggregateDialog).Single(x=>x.Height==180).Text==aggregate.Json&&Find<TextBlock>(aggregateDialog).Any(x=>x.Text==app.L(DoctorAssistantSession.Scope)),"Doctor aggregate exact snapshot and whole-result limits visible");aggregateDialog.Close();aggregateDialog.FinishAsync().GetAwaiter().GetResult();
        var sample=DoctorAssistantSummary.Monitor(new(0,null,null,null,null,CpuSampleStatus.Available));var monitorDialog=new AssistantDialog(app,settings,Array.Empty<AssistantChoice>(),Array.Empty<string>(),"Explain this sample",default,doctorSnapshot:sample);
        check(Find<TextBox>(monitorDialog).Single(x=>x.Height==180).Text==sample.Json&&Find<TextBlock>(monitorDialog).Any(x=>x.Text==app.L(UsageNotices.AssistantScope)),"Monitor preview uses a single-sample scope and explicit manual resume notice");monitorDialog.Close();monitorDialog.FinishAsync().GetAwaiter().GetResult();
        var namedFacts=new[]{new DoctorFact("Largest working sets","{0}: {1} MB resident memory",new object[]{"PRIVATE-A",1d}),new DoctorFact("Largest working sets","{0}: {1} MB resident memory",new object[]{"PRIVATE-B",2d})};
        var names=new AssistantDialog(app,settings,Array.Empty<AssistantChoice>(),Array.Empty<string>(),"Explain",default,doctorFacts:namedFacts);var nameButtons=Find<Button>(names).ToArray();var namePrepare=nameButtons.Single(x=>Equals(x.Content,app.L("Prepare Request Preview")));var nameSend=nameButtons.Single(x=>Equals(x.Content,app.L("Send Reviewed Request")));var namePreview=Find<TextBox>(names).Single(x=>x.Height==260);var nameReport=Find<TextBox>(names).Single(x=>x.Height==180);var nameCheck=Find<CheckBox>(names).Single(x=>Equals(x.Content,app.L("Include only the reported labels I select for this request (may contain private text)")));var nameReview=Find<CheckBox>(names).Single(x=>Equals(x.Content,app.L("I reviewed the full JSON request and destination.")));var nameList=Find<ListView>(names).Single();
        namePrepare.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(nameCheck.IsChecked==false&&!namePreview.Text.Contains("PRIVATE"),"Doctor labels default off and absent from request");nameCheck.IsChecked=true;check(namePreview.Text.Length==0&&nameReport.Text.Length==0&&!nameSend.IsEnabled,"Label consent invalidates both exact previews and send");
        nameList.SelectedItems.Add(nameList.Items[1]);namePrepare.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(nameReport.Text.Contains("PRIVATE-B")&&!nameReport.Text.Contains("PRIVATE-A")&&namePreview.Text.Contains("PRIVATE-B"),"Only explicitly selected Doctor label enters both complete previews");check(Find<TextBlock>(names).Any(x=>x.Text==app.L(AssistantDialog.NamedDoctorScope)),"Including labels shows accurate private-text scope");nameReview.IsChecked=true;check(nameSend.IsEnabled,"Reviewed named request requires its own explicit send");
        nameList.SelectedItems.Clear();nameList.SelectedItems.Add(nameList.Items[0]);check(namePreview.Text.Length==0&&nameReport.Text.Length==0&&nameReview.IsChecked==false&&!nameSend.IsEnabled,"Changing label selection invalidates old review and result");nameCheck.IsChecked=false;namePrepare.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));check(!namePreview.Text.Contains("PRIVATE")&&nameReport.Text==DoctorAssistantReport.Create(namedFacts),"Turning labels off restores exact default numeric report");names.Close();names.FinishAsync().GetAwaiter().GetResult();
        var emptyIssues=Array.Empty<DuplicateIssue>();var emptyProjects=new ProjectFolderResult(Array.Empty<ProjectFolder>(),Array.Empty<ProjectFolderIssue>());var emptyLarge=new LargeFileResult(Array.Empty<LargeFile>(),Array.Empty<LargeFileIssue>(),false,0,0);
        Window[] resultWindows={new FolderMapDialog(app,"C:\\PRIVATE",folder),new LargeFilesDialog(app,"C:\\PRIVATE",folder,emptyLarge),new ProjectFoldersDialog(app,"C:\\PRIVATE",folder,emptyProjects),new DuplicateFilesDialog(app,"C:\\PRIVATE",folder,new(Array.Empty<DuplicateGroup>(),emptyIssues,0,0,0,false,false)),new TextSimilarityDialog(app,"C:\\PRIVATE",folder,new(Array.Empty<SimilarTextPair>(),emptyIssues,0,0,0,0,0,0,false,false,false,false)),new PhotoSimilarityDialog(app,"C:\\PRIVATE",folder,new(Array.Empty<SimilarPhotoPair>(),emptyIssues,0,0,0,0,0,0,false,false,false)),new AppMemoryDialog(app,new(default,Array.Empty<AppMemoryProcess>(),Array.Empty<AppMemoryGroup>(),false,false,false,false)),new InstalledAppsDialog(app,new(default,Array.Empty<InstalledAppRecord>(),Array.Empty<RegistrationRootResult>())),new StartupDialog(app,new(default,Array.Empty<StartupRecord>(),Array.Empty<StartupRootResult>()))};
        foreach(var parent in resultWindows)
        {
            var footer=((DockPanel)parent.Content).Children.OfType<Panel>().Single(x=>DockPanel.GetDock(x)==Dock.Bottom);var session=new DoctorAssistantSession(app,parent,footer,aggregate,default);
            check(ReferenceEquals(footer.Children[0],session.Button)&&session.Button.ToolTip as string==app.L(DoctorAssistantSession.Scope),"Doctor result footer supports owned explicit explanation: "+parent.GetType().Name);
            parent.Close();session.FinishAsync().GetAwaiter().GetResult();check(!session.Button.IsEnabled,"Closed Doctor session cannot open a later assistant");
        }
        // No Send/SaveKey/RemoveKey button is invoked: never access the user's
        // real credential set, network, clipboard or execute a suggested action.
    }
}
